code-intervals:
def merge_intervals(intervals):
 result=[]
 for lo,hi in sorted(intervals):
  if hi<=lo: raise ValueError()
  if result and lo<=result[-1][1]: result[-1]=(result[-1][0],max(hi,result[-1][1]))
  else: result.append((lo,hi))
 return result

code-event-order:
def latest(events):
 best={}
 for event in events:
  key=event['key']
  if key not in best or event['version']>=best[key]['version']: best[key]=event
 return {key:event['value'] for key,event in best.items()}

